func longestPalindrome(s string) string {
    start, maxLen := 0, 0
    expand := func(l, r int) {
        for l >= 0 && r < len(s) && s[l] == s[r] {
            l--
            r++
        }
        if r-l-1 > maxLen {
            start = l + 1
            maxLen = r - l - 1
        }
    }
    for i := range s {
        expand(i, i)   // 奇数长度
        expand(i, i+1) // 偶数长度
    }
    return s[start : start+maxLen]
}
